import httpx

def stream_events(url):
    with httpx.stream("GET", url, headers={"Accept": "text/event-stream"}) as response:
        event_type = None
        data_lines = []
        for line in response.iter_lines():
            if line.startswith("event:"):
                event_type = line[len("event:"):].strip()
            elif line.startswith("data:"):
                data_lines.append(line[len("data:"):].strip())
            elif line == "":
                if data_lines:
                    yield event_type, "\n".join(data_lines)
                event_type, data_lines = None, []

for event_type, data in stream_events("https://tools.example.com/mcp/events"):
    print(event_type, data)

import asyncio

class SSEDispatcher:
    def __init__(self):
        self.pending = {}

    async def wait_for(self, request_id):
        future = asyncio.get_event_loop().create_future()
        self.pending[request_id] = future
        return await future

    def dispatch(self, message):
        request_id = message.get("id")
        if request_id in self.pending:
            self.pending.pop(request_id).set_result(message)
        else:
            handle_notification(message)

import time

def robust_stream(url, last_event_id=None):
    while True:
        headers = {"Accept": "text/event-stream"}
        if last_event_id:
            headers["Last-Event-ID"] = last_event_id
        try:
            for event_id, event_type, data in connect_and_stream(url, headers):
                last_event_id = event_id
                yield event_type, data
        except ConnectionError:
            time.sleep(2)
            continue

